create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, first_name text not null, last_name text not null, avatar_path text, role public.app_role not null default 'pronostiqueur', is_goalkeeper boolean not null default false, is_active boolean not null default true, archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create table public.seasons (id uuid primary key default gen_random_uuid(), name text not null unique, is_open boolean not null default false, archived_at timestamptz, created_at timestamptz not null default now()); create unique index seasons_one_open_idx on public.seasons ((is_open)) where is_open = true;;
